import { NextRequest, NextResponse } from 'next/server';

const NUM_WORDS: Record<string, number> = {
  isa: 1, isang: 1, dalawa: 2, dalawang: 2, tatlo: 3, tatlong: 3,
  apat: 4, apatna: 4, lima: 5, limang: 5, anim: 6, animna: 6,
  pito: 7, pitong: 7, walo: 8, walong: 8, siyam: 9, siyamna: 9,
  sampu: 10, sampung: 10, labing: 11, dose: 12, labindalawa: 12,
};

const CAT_KEYWORDS: Record<string, string[]> = {
  food: ['kain', 'food', 'biskwit', 'biscuit', 'siomai', 'rice', 'kanin', 'lunch', 'dinner', 'breakfast', 'merienda', 'canteen', 'karinderya', 'milk', 'tea', 'kape', 'coffee', 'snack', 'tapsilog', 'burger', 'jollibee', 'mcdo', 'pizza'],
  transpo: ['jeep', 'bus', 'tricycle', 'trike', 'gas', 'pamasahe', 'fare', 'grab', 'taxi', 'angkas', 'mrt', 'lrt', 'sakay'],
  school: ['print', 'printing', 'book', 'libro', 'notebook', 'ballpen', 'papel', 'yellow', 'supplies', 'project', 'school', 'tuition', 'bond'],
  load: ['load', 'data', 'wifi', 'internet', 'promo', 'sim', 'cellphone', 'cp', 'vpn'],
  gala: ['movie', 'cinema', 'mall', 'gala', 'outing', 'inom', 'party', 'concert', 'game', 'ticket'],
};

function extractNumbers(msg: string): number[] {
  const tokens = msg.toLowerCase().split(/[\s,\-]+/);
  const nums: number[] = [];
  for (const t of tokens) {
    const clean = t.replace(/[^a-z0-9.]/g, '');
    if (!clean) continue;
    if (/^\d+(\.\d+)?$/.test(clean)) nums.push(Number(clean));
    else if (NUM_WORDS[clean] != null) nums.push(NUM_WORDS[clean]);
  }
  return nums;
}

function detectCategory(msg: string): string {
  const lower = msg.toLowerCase();
  for (const [cat, words] of Object.entries(CAT_KEYWORDS)) {
    if (words.some(w => lower.includes(w))) return cat;
  }
  return 'other';
}

function isRemoveIntent(msg: string): boolean {
  return /\b(delete|remove|bura|tanggal|alis|iban|palitan|mali|wrong|hindi tama)\b/i.test(msg);
}

export async function POST(req: NextRequest) {
  try {
    const { message } = await req.json();
    if (!message || typeof message !== 'string') {
      return NextResponse.json({ error: 'no message' }, { status: 400 });
    }

    const lower = String(message).toLowerCase();

    if (isRemoveIntent(lower)) {
      return NextResponse.json({ action: 'remove' });
    }

    const nums = extractNumbers(lower);
    const hasEach = /\b(tig|bawat|each|kada)\b/.test(lower);
    let amount = 0;

    if (hasEach && nums.length >= 2) {
      amount = nums[0] * nums[1];
    } else if (nums.length === 1) {
      amount = nums[0];
    } else if (nums.length >= 2) {
      amount = Math.max(...nums);
    }

    if (!amount || amount <= 0) {
      return NextResponse.json({ error: 'no amount' });
    }

    const category = detectCategory(lower);
    const note = String(message).slice(0, 40);

    return NextResponse.json({ action: 'add', amount, category, note });
  } catch {
    return NextResponse.json({ error: 'fail' });
  }
}
